import { describe, expect, test } from "vitest";
import fixtures from "./shopper-generation-fixtures.json";
import rules from "./shopper-generation-rules.json";
import { inferShopperMix, recommendFormats, type Generation } from "./shopper-generation";

// Golden fixtures generated by the desktop engine (InfluencerButler
// `npm run sync:shopper-rules`). The TypeScript port must reproduce them
// exactly, so a desktop rules change without a re-sync fails here.
describe("shopper-generation parity with the desktop engine", () => {
  test("fixtures were generated from this rules version", () => {
    expect(fixtures.rulesVersion).toBe(rules.version);
  });

  for (const c of fixtures.cases) {
    test(c.name, () => {
      const est = inferShopperMix(c.product, c.profile as Partial<Record<Generation, number>> | null);
      expect({
        mix: est.mix,
        primary: est.primary,
        confidence: est.confidence,
        categoryId: est.categoryId,
        matchedOn: est.matchedOn,
        reasons: est.reasons,
        formats: recommendFormats(est.mix).map((f) => ({ id: f.id, score: f.score })),
      }).toEqual(c.expected);
    });
  }
});
